// Встроенные спорные случаи промпта W2: как узнать их в списке пользователя, решение по умолчанию
// и формулировка для поправки. 19.10.2026: AI — на любом языке, fullstack — только с бэкендом не на Node.js и не на
// Python (fullstack на Node/Python — apply по правилам). Прежние подписи («AI на JS/TS», «fullstack») узнаются:
// сохранённые списки не ломаются
const BUILTIN_CASES = {
  vue: {
    aliases: ['vue без react', 'vue', 'nuxt', 'vue/nuxt', 'vue nuxt'],
    default: 'maybe',
    prompt: 'основной стек — Vue (Vue.js, Nuxt), а React нет в обязательных требованиях',
  },
  fullstack: {
    aliases: [
      'fullstack не на node/python',
      'fullstack не на node',
      'fullstack',
      'full stack',
      'full-stack',
      'фулстек',
      'фуллстек',
      'fullstack с react',
    ],
    default: 'maybe',
    prompt: 'fullstack, где бэкенд не на Node.js и не на Python, или упор на бэкенд',
  },
  ai: {
    aliases: [
      'ai-разработка',
      'ai разработка',
      'разработка на ai',
      'ai на любом языке',
      'ai',
      'ai на js/ts',
      'ai на js',
      'ai на ts',
      'ai js/ts',
      'ai js',
    ],
    default: 'apply',
    prompt: 'разработка на AI на любом языке (интеграции LLM, AI-агенты, RAG), кроме мобильной',
  },
  react_native: {
    aliases: ['react native', 'react-native', 'rn'],
    default: 'skip',
    prompt: 'мобильная разработка на React Native — основная работа',
  },
};
const normCase = (text) =>
  String(text ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\s+/g, ' ')
    .trim();
// Встроенный случай, которому соответствует запись пользователя, или null
const builtinOf = (text) =>
  Object.keys(BUILTIN_CASES).find((key) => BUILTIN_CASES[key].aliases.includes(normCase(text))) ?? null;

// Слово списка: буквы, цифры, пробел и . + # ' - ; «*» в конце — любое окончание. Без скобок и кавычек:
// они сломали бы язык запросов hh
const WORD_RE = /^[\p{L}\p{N}][\p{L}\p{N} .+#'’-]{0,28}\*?$/u;

// items — $('Settings').all() (строки таблицы settings) → { имя: значение }
function loadSettings(items) {
  const stored = {};
  for (const item of items ?? []) {
    const row = item?.json ?? item;
    if (!row?.name || !(row.name in SETTINGS)) continue;
    try {
      stored[row.name] = JSON.parse(row.value_json);
    } catch {
      // битое значение — останется по умолчанию
    }
  }
  const out = {};
  for (const [name, spec] of Object.entries(SETTINGS)) {
    const value = stored[name];
    out[name] = value !== undefined && validSetting(spec, value) ? value : spec.default;
  }
  return out;
}

function validSetting(spec, value) {
  if (spec.options) return spec.options.some((o) => o === value);
  if (spec.words) {
    return Array.isArray(value) && value.length >= (spec.min ?? 1) && value.length <= 40 && value.every((w) => WORD_RE.test(w));
  }
  if (spec.roles) return Array.isArray(value) && value.length <= 10 && value.every((id) => /^\d{1,4}$/.test(String(id)));
  if (spec.formats) return Array.isArray(value) && value.length > 0 && value.every((f) => WORK_FORMATS.includes(f));
  if (spec.area) {
    return value === null || (Boolean(value) && /^\d{1,7}$/.test(String(value.id)) && typeof value.name === 'string' && value.name.length <= 80);
  }
  if (spec.education) return Array.isArray(value) && value.every((e) => EDUCATION.includes(e));
  if (spec.list) return Array.isArray(value) && value.every((v) => spec.list.includes(v));
  if (spec.cases) {
    return (
      Array.isArray(value) &&
      value.length <= 20 &&
      value.every((c) => CASE_RE.test(c?.case ?? '') && ['apply', 'maybe', 'skip'].includes(c?.decision))
    );
  }
  if (spec.stamp) return typeof value === 'string' && (value === '' || Number.isFinite(Date.parse(value)));
  if (spec.text) return typeof value === 'string' && value.length <= spec.text;
  if (spec.tz) {
    try {
      return typeof value === 'string' && Boolean(value) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: value }));
    } catch {
      return false;
    }
  }
  if (spec.lines) return validLines(value, spec.lines);
  if (spec.history) return validHistory(value, spec.history);
  if (spec.cv) return validCv(value);
  if (spec.resumes) return validResumes(value);
  if (spec.resumeData) return validResumeData(value);
  if (spec.object) return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
  if (spec.rules) {
    return (
      Boolean(value) &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      Object.entries(value).every(([key, lines]) => RULE_KEYS.includes(key) && validLines(lines, 400))
    );
  }
  return false;
}

// Форматы работы и уровни образования — значения параметров поиска hh
const WORK_FORMATS = ['REMOTE', 'HYBRID', 'ON_SITE', 'FIELD_WORK'];
const EDUCATION = ['not_required_or_not_specified', 'special_secondary', 'higher'];

// Разделы правил оценки (llm.rules) и список строк: до 20 строк, каждая — до max знаков
const RULE_KEYS = ['skip', 'maybe', 'apply', 'ignore', 'notes'];
const validLines = (lines, max) =>
  Array.isArray(lines) && lines.length <= 20 && lines.every((l) => typeof l === 'string' && l.length <= max);

// Версии резюме (resume.history): текст резюме и «Дополнительно» — в пределах profile.resume и profile.extra
const validHistory = (list, max) =>
  Array.isArray(list) &&
  list.length <= max &&
  list.every(
    (v) =>
      Boolean(v) &&
      typeof v === 'object' &&
      typeof v.at === 'string' &&
      typeof v.resume === 'string' &&
      v.resume.length <= SETTINGS['profile.resume'].text &&
      typeof (v.extra ?? '') === 'string' &&
      String(v.extra ?? '').length <= SETTINGS['profile.extra'].text &&
      (v.cv === undefined || v.cv === null || validCv(v.cv)),
  );

// Разметка резюме (cv): места работы с уникальными id, 1–5 резюме, ключевые навыки — не больше 30 (предел hh)
function validCv(v) {
  if (v === null) return true;
  const str = (x, max) => typeof x === 'string' && x.length <= max;
  const max = SETTINGS['profile.resume'].text;
  const places = Array.isArray(v?.places) ? v.places : null;
  return (
    Boolean(v) &&
    typeof v === 'object' &&
    v.v === 1 &&
    Boolean(places) &&
    places.length <= 30 &&
    new Set(places.map((p) => p?.id)).size === places.length &&
    places.every(
      (p) =>
        /^e\d{1,3}$/.test(p?.id ?? '') &&
        (p.hhId === null || Number.isFinite(p.hhId)) &&
        str(p.company, 512) &&
        str(p.period, 200) &&
        str(p.position, 512) &&
        str(p.description, max),
    ) &&
    Array.isArray(v.resumes) &&
    v.resumes.length >= 1 &&
    v.resumes.length <= 5 &&
    v.resumes.every(
      (r) =>
        /^r\d$/.test(r?.id ?? '') &&
        (r.hh === null || (Boolean(r.hh) && str(r.hh.hash, 64) && str(r.hh.title, 200))) &&
        str(r.template, max + 2000) &&
        str(r.title, 200) &&
        str(r.about, max) &&
        Array.isArray(r.keySkills) &&
        r.keySkills.length <= 30 &&
        r.keySkills.every((k) => typeof k === 'string' && k.length > 0 && k.length <= 100),
    )
  );
}

// Поля резюме r2–r5 (resume.<id>) → ключи настроек, которые они подменяют у основного резюме. Своё у резюме всё,
// что зависит от профессии: текст, факты, правила оценки и фильтра, поиск, стиль писем. Общее: подпись, контакт,
// пояс, нейросеть, порог откликов, чёрный список. Проверка значения — по спецификации ключа
const RESUME_FIELDS = {
  resume: 'profile.resume',
  extra: 'profile.extra',
  facts: 'profile.facts',
  about: 'profile.about',
  preset: 'profile.preset',
  rules: 'llm.rules',
  cases: 'llm.cases',
  roles: 'search.roles',
  in_name: 'search.in_name',
  anywhere: 'search.anywhere',
  formats: 'search.formats',
  area: 'search.area',
  education: 'search.education',
  stop_words: 'filter.stop_words',
  rules_off: 'filter.rules_off',
  examples: 'letters.examples',
  prompt: 'letters.prompt',
};

// Слова «в названии» у резюме могут быть пустыми, если искать по всему тексту (у основного резюме — минимум одно слово)
const resumeSpec = (field) => (field === 'in_name' ? { ...SETTINGS['search.in_name'], min: 0 } : SETTINGS[RESUME_FIELDS[field]]);

// Данные резюме: null (нет) или объект только из известных полей с допустимыми значениями
const validResumeData = (v) =>
  v === null ||
  (Boolean(v) &&
    typeof v === 'object' &&
    !Array.isArray(v) &&
    Object.entries(v).every(([field, value]) => field in RESUME_FIELDS && validSetting(resumeSpec(field), value)));

// Список резюме: 1–5 записей, r1 обязателен, id уникальны (r1–r5), у привязки к hh — hash и название
const validResumes = (list) =>
  Array.isArray(list) &&
  (list.length === 0 ||
    (list.length <= 5 &&
      list.some((r) => r?.id === 'r1') &&
      new Set(list.map((r) => r?.id)).size === list.length &&
      list.every(
        (r) =>
          /^r[1-5]$/.test(r?.id ?? '') &&
          typeof r.name === 'string' &&
          r.name.trim().length > 0 &&
          r.name.length <= 60 &&
          typeof r.active === 'boolean' &&
          (r.hh === null ||
            (Boolean(r.hh) && typeof r.hh.hash === 'string' && r.hh.hash.length <= 64 && typeof r.hh.title === 'string' && r.hh.title.length <= 200)),
      )));

// Текст резюме для промптов W2 и W5: резюме и «Дополнительно» (то, что человек дописал сам) — своим разделом
function resumeText(s) {
  const resume = String(s['profile.resume'] ?? '').trim();
  const extra = String(s['profile.extra'] ?? '').trim();
  return extra ? `${resume}\n\n## Дополнительно\n${extra}` : resume;
}

// Спорный случай: 2–80 знаков, без угловых скобок и обратных кавычек
const CASE_RE = /^[^<>`]{2,80}$/u;
const DECISION_WORDS = {
  apply: 'apply',
  '🟢': 'apply',
  откликнусь: 'apply',
  maybe: 'maybe',
  '🟡': 'maybe',
  возможно: 'maybe',
  skip: 'skip',
  '🔴': 'skip',
  мимо: 'skip',
};

// Список спорных случаев из ответа пользователя: «Vue без React: maybe, Angular: skip» → [{ case, decision }].
// Случаи — через запятую; если в описании нужна запятая — через «;» или с новой строки. Между случаем и решением —
// «:», «=» или тире; решение — apply, maybe, skip (или 🟢 🟡 🔴, откликнусь, возможно, мимо).
// «-» — очистить список. { error } — что не так
function parseCases(text) {
  const raw = String(text ?? '').trim();
  if (raw === '-' || raw === '—') return { cases: [] };
  const parts = (/[;\n]/.test(raw) ? raw.split(/[;\n]+/) : raw.split(',')).map((x) => x.trim()).filter(Boolean);
  if (!parts.length) return { error: 'список пуст (очистить — пришли «-»)' };
  if (parts.length > 20) return { error: `случаев ${parts.length}, можно до 20` };
  const cases = [];
  for (const part of parts) {
    const m = part.match(/^(.+?)\s*[:=—–]\s*(\S+)$/u) ?? part.match(/^(.+?)\s+-\s+(\S+)$/u);
    const decision = m && DECISION_WORDS[m[2].toLowerCase()];
    if (!decision) return { error: `«${part}»: нужно «случай: решение», решение — apply, maybe или skip` };
    const name = m[1].trim();
    if (!CASE_RE.test(name)) return { error: `«${name}»: описание случая — от 2 до 80 знаков, без < > и \`` };
    const existing = cases.find((c) => normCase(c.case) === normCase(name));
    if (existing) existing.decision = decision;
    else cases.push({ case: name, decision });
  }
  return { cases };
}

// Список для показа и вопроса: «Vue без React: maybe, fullstack: maybe»
const casesText = (cases) => cases.map((c) => `${c.case}: ${c.decision}`).join(', ');

// Список слов из ответа пользователя: «frontend, react, AI» → ['frontend', 'react', 'AI'];
// { error } — если список пуст, длиннее 40 слов или в слове недопустимые символы
function parseWords(text) {
  const seen = new Map();
  for (const w of String(text ?? '').split(/[,;\n]+/).map((x) => x.trim()).filter(Boolean)) {
    if (!seen.has(w.toLowerCase())) seen.set(w.toLowerCase(), w);
  }
  const words = [...seen.values()];
  if (!words.length) return { error: 'список пуст' };
  if (words.length > 40) return { error: `слов ${words.length}, можно до 40` };
  const bad = words.find((w) => !WORD_RE.test(w));
  if (bad) return { error: `«${bad}»: только буквы, цифры, пробел и . + # ' -, «*» в конце, до 30 знаков` };
  return { words };
}

// Включить или выключить элемент списка (filter.rules_off)
const toggleListItem = (list, item) => (list.includes(item) ? list.filter((x) => x !== item) : [...list, item]);

// Слово списка → регулярка с границами слова (латиница, кириллица, цифры); «*» в конце — любое окончание
function wordsRegex(words) {
  const parts = words.map((w) => {
    const stem = w.replace(/\*$/, '').replace(/[.+#'’-]/g, (c) => `\\${c}`);
    return w.endsWith('*') ? `${stem}[a-zа-яё0-9]*` : stem;
  });
  return new RegExp(`(^|[^a-zа-яё0-9])(${parts.join('|')})([^a-zа-яё0-9]|$)`, 'i');
}

// Следующее значение по кругу — кнопка «▸» (только у настроек с вариантами)
function nextSetting(name, current) {
  const { options } = SETTINGS[name];
  return options[(options.findIndex((o) => o === current) + 1) % options.length];
}

// Расписание сбора для n8n/shared/schedule.js
function scheduleFrom(s) {
  const [dayFrom, dayTo] = String(s['collect.day_window']).split('-').map(Number);
  return {
    dayFrom,
    dayTo,
    dayEvery: s['collect.day_every'],
    nightEvery: s['collect.night_every'],
    paused: s['collect.paused'],
  };
}

// Расписание сбора W1 по Москве (UTC+3, без перехода на летнее время). С 07.10.2026 задаётся в боте
// (⚙️ Настройки → 🕐 Сбор, n8n/shared/settings.js → scheduleFrom), сбор запускают «часы» W8 Clock.
// sch = { dayFrom, dayTo, dayEvery, nightEvery, paused }: днём [dayFrom, dayTo) — каждые dayEvery мин, ночью — каждые
// nightEvery мин (0 — ночью не собирать). Слоты выровнены по полуночи МСК, шаг сетки — 15 мин.
// По умолчанию (решение пользователя 07.10.2026) — 29 сборов в сутки: днём 07:00–17:30 каждые 30 мин,
// ночью 18, 20, 22, 00, 02, 04, 06.
// Общий код W1 «Score job», W6 «Summary», W7 «Render», W8 «Due»: строка «// @include n8n/shared/schedule.js».

const COLLECT_STEP = 15 * 60 * 1000;
const DEFAULT_SCHEDULE = { dayFrom: 7, dayTo: 18, dayEvery: 30, nightEvery: 120, paused: false };

// Момент t (мс, кратен 15 мин) — сбор по расписанию?
function isCollectSlot(t, sch = DEFAULT_SCHEDULE) {
  if (sch.paused) return false;
  const msk = new Date(t + 3 * 3600 * 1000);
  const hour = msk.getUTCHours();
  const every = hour >= sch.dayFrom && hour < sch.dayTo ? sch.dayEvery : sch.nightEvery;
  return every > 0 && (hour * 60 + msk.getUTCMinutes()) % every === 0;
}

// Сколько сборов по расписанию в промежутке (from, to]
function countCollectSlots(from, to, sch = DEFAULT_SCHEDULE) {
  let n = 0;
  for (let t = Math.floor(from / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP; t <= to; t += COLLECT_STEP) {
    if (isCollectSlot(t, sch)) n++;
  }
  return n;
}

// Ближайший сбор по расписанию после момента t; null — на паузе
function nextCollect(t, sch = DEFAULT_SCHEDULE) {
  if (sch.paused) return null;
  let s = Math.floor(t / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP;
  for (let i = 0; i < 2 * 96; i++, s += COLLECT_STEP) if (isCollectSlot(s, sch)) return s;
  return null;
}

// Сборов в сутки по расписанию
const collectsPerDay = (sch = DEFAULT_SCHEDULE) => countCollectSlots(0, 24 * 3600 * 1000, { ...sch, paused: false });

// Расписание словами: «днём 07–18 МСК каждые 30 мин, ночью каждые 2 ч»
function describeSchedule(sch = DEFAULT_SCHEDULE) {
  const every = (m) => (m % 60 ? `${m} мин` : `${m / 60} ч`);
  const pad = (n) => String(n).padStart(2, '0');
  const night = sch.nightEvery > 0 ? `ночью каждые ${every(sch.nightEvery)}` : 'ночью не собирать';
  return `днём ${pad(sch.dayFrom)}–${pad(sch.dayTo)} МСК каждые ${every(sch.dayEvery)}, ${night}`;
}

// Расписание стража healthchecks.io: OnCalendar (строка дня и строка ночи) и запас (grace, с)
function onCalendar(sch = DEFAULT_SCHEDULE) {
  const pad = (n) => String(n).padStart(2, '0');
  const minutes = [];
  for (let m = 0; m < 60; m += Math.min(sch.dayEvery, 60)) minutes.push(pad(m));
  const lines = [`${pad(sch.dayFrom)}..${pad(sch.dayTo - 1)}:${minutes.join(',')} Europe/Moscow`];
  if (sch.nightEvery > 0) {
    const hours = [];
    for (let h = 0; h < 24; h++) {
      if ((h < sch.dayFrom || h >= sch.dayTo) && (h * 60) % sch.nightEvery === 0) hours.push(pad(h));
    }
    if (hours.length) lines.push(`${hours.join(',')}:00 Europe/Moscow`);
  }
  return { schedule: lines.join('\n'), grace: (sch.dayEvery + 20) * 60 };
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const from = (name) => {
  try {
    return $(name).all().map((i) => i.json);
  } catch {
    return []; // ветка не выполнялась: устаревших или закрытых не было
  }
};

const DAY = 24 * 3600 * 1000;
const now = Date.now();
const since = now - DAY;
const at = (s) => Date.parse(s) || 0;
const rows = $('All rows').all().map((i) => i.json).filter((r) => r.id);
const settings = loadSettings($('Settings').all());
const expired = new Set(from('Expire rows').map((r) => r.id));
const archived = new Set(from('Archive status').map((r) => r.id));

// Воронка: новые строки за сутки (кроме бэкфилла seen) → отсеяно фильтром → оценено нейросетью
const fresh = rows.filter((r) => at(r.createdAt) >= since && r.status !== 'seen');
const rejected = fresh.filter((r) => r.status === 'rejected');
const reasons = {};
for (const r of rejected) {
  for (const reason of String(r.reasons).split(', ').filter(Boolean)) {
    const key = reason.replace(/:.*$/, '');
    reasons[key] = (reasons[key] ?? 0) + 1;
  }
}
const topReasons = Object.entries(reasons)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 4)
  .map(([k, n]) => `${esc(k)} ${n}`)
  .join(' · ');
// Время оценки — card_at (пишет W2); у строк до этапа 5 его нет — берём время создания
const scored = rows.filter((r) => r.decision && at(r.card_at || r.createdAt) >= since);
const count = (list, f) => list.filter(f).length;
// Подборка hh «по резюме» (21.10.2026): что она дала сверх обычного поиска (via = resume) — строка, пока подборка хоть
// раз что-то принесла
const viaResume = (r) => r.via === 'resume';
const resumeFresh = fresh.filter(viaResume);
const resumeScored = scored.filter(viaResume);
const resumeLine = rows.some(viaResume)
  ? `📄 Из них только из подборки hh по резюме: ${resumeFresh.length} → оценено ${resumeScored.length}${resumeScored.length ? ` (🟢 ${count(resumeScored, (r) => r.decision === 'apply')})` : ''}`
  : '';

// Решения пользователя за сутки (по времени последнего изменения строки) и отправленные отклики
const mine = rows.filter((r) => r.my_decision && at(r.updatedAt) >= since);
const sent = count(rows, (r) => at(r.applied_at) >= since);

// Хвосты после этого запуска
const tailsWaiting = count(rows, (r) => r.status === 'waiting' && !expired.has(r.id) && !archived.has(r.id));
const tailsApproved = count(rows, (r) => r.status === 'approved' && !archived.has(r.id));

// Теневой режим: оценки пользователя там, где решение нейросети известно, — с метки «🔄 Теневой заново»
// (n8n/shared/shadow.js)
const shadow = shadowStats(rows, settings['llm.shadow_since']);

// Сбои: запуски n8n за сутки (публичный API), туннель, хвост оценки нейросетью
const NAMES = {
  jobHunterS0Setup: 'S0 таблицы',
  jobHunterS1TgTst: 'S1 тест Telegram',
  jobHunterW0Check: 'W0 проверка hh',
  jobHunterW4Error: 'W4 тревоги',
  jobHunterW1Colle: 'W1 сбор',
  jobHunterW2Score: 'W2 оценка',
  jobHunterW3Teleg: 'W3 кнопки',
  jobHunterW5Lettr: 'W5 письма',
  jobHunterW6Summ1: 'W6 сводка',
  jobHunterW7Menu1: 'W7 меню',
  jobHunterW8Clock: 'W8 часы',
  jobHunterW9Robot: 'W9 робот',
  jobHunterW10Inbx: 'W10 входящие',
};
const executionsBody = $('Executions').first().json;
const executions = (executionsBody.data ?? []).filter((e) => at(e.startedAt) >= since);
const errors = executions.filter((e) => e.status === 'error' || e.status === 'crashed');
const errorsBy = {};
for (const e of errors) errorsBy[NAMES[e.workflowId] ?? e.workflowId] = (errorsBy[NAMES[e.workflowId] ?? e.workflowId] ?? 0) + 1;

// Сборы W1 по расписанию — журнал runs (сколько положено — n8n/shared/schedule.js). Окно — сутки
// до «сейчас − 10 мин»: сбор в 06:00 идёт одновременно со сводкой и ещё не закончился
const windowEnd = now - 10 * 60 * 1000;
const windowStart = windowEnd - DAY;
// Расписание — из настроек бота (⚙️ → 🕐 Сбор). На паузе сборов не ждём — и не тревожим
const sch = scheduleFrom(settings);
const expected = countCollectSlots(windowStart, windowEnd, sch);
const collected = count(
  $('Runs')
    .all()
    .map((i) => i.json),
  (r) =>
    ['schedule', 'catchup'].includes(r.kind) &&
    r.status === 'ok' &&
    at(r.started_at) > windowStart &&
    at(r.started_at) <= windowEnd,
);
// Ждут оценки дольше 30 мин: W2 запускается сразу после сбора, свежие строки detailed — норма
// (scoring — W2 сейчас оценивает; застрявшие в scoring вернёт ветка «Unstick»). Время — когда строка стала detailed
// (updatedAt), а не создана: строки из очереди и разового догона создавались давно (19.10.2026)
const pendingScore = count(
  rows,
  (r) => ['detailed', 'scoring'].includes(r.status) && at(r.updatedAt) < now - 30 * 60 * 1000,
);
const tunnelCode = $input.first().json.statusCode;
const tunnelOk = !$env.NGROK_DOMAIN || tunnelCode === 403; // 403 = туннель жив, политика не пускает чужих

const problems = [];
if (executionsBody.error || !executionsBody.data) problems.push('нет данных о запусках n8n');
if (!sch.paused && collected < expected) problems.push(`сборов ${collected} из ${expected}`);
if (errors.length)
  problems.push(
    `ошибок ${errors.length} (${Object.entries(errorsBy)
      .map(([k, n]) => `${k} ${n}`)
      .join(' · ')})`,
  );
if (!tunnelOk) problems.push(`туннель не отвечает (${tunnelCode ?? 'нет ответа'}) — кнопки не работают`);
if (pendingScore) problems.push(`ждут оценки нейросетью: ${pendingScore}`);

// Робот-отклик (этап 6): отклики за сутки и его здоровье — если он включён в ⚙️. Автоотклик (6.1c): сколько из них
// робот взял сам (🤖), сколько ты убрал из очереди (⛔) и к скольким письмо не вышло. Время попытки — apply_at
// (у строк до 20.10.2026 его нет — по updatedAt)
const robotOn = settings['apply.enabled'];
const tried = (r) => (at(r.apply_at) || at(r.updatedAt)) >= since;
const robotRows = rows.filter((r) => r.apply_by === 'robot' && at(r.applied_at) >= since);
const robotAuto = count(robotRows, (r) => r.apply_mode === 'auto');
const robotManual = count(rows, (r) => ['test', 'external', 'hidden'].includes(r.apply_result) && tried(r));
const robotErrors = count(rows, (r) => r.apply_result === 'error' && r.status === 'approved' && tried(r));
const robotStopped = count(rows, (r) => r.apply_result === 'stopped' && at(r.apply_at) >= since);
const robotNoLetter = count(rows, (r) => r.apply_result === 'no_letter' && at(r.apply_at) >= since);
const robotQueue = count(rows, (r) => r.apply_state);
const robotLineText =
  robotOn || robotRows.length || robotQueue
    ? `🚀 Робот: ${robotRows.length}${robotRows.length ? ` (${robotAuto ? `🤖 авто ${robotAuto} · ` : ''}✉️ ${count(robotRows, (r) => r.apply_letter === 'attached')} · 💬 ${count(robotRows, (r) => r.apply_letter === 'chat')})` : ''}${robotManual ? ` · 🧩 вручную ${robotManual}` : ''}${robotErrors ? ` · ⚠️ ${robotErrors}` : ''}${robotStopped ? ` · ⛔ убрал ${robotStopped}` : ''}${robotNoLetter ? ` · ✉️ письмо не вышло ${robotNoLetter}` : ''}${robotQueue ? ` · в очереди ${robotQueue}` : ''}${settings['apply.paused'] ? ' · ⏸ пауза' : ''}${settings['apply.enabled'] && settings['apply.auto'] ? ' · 🤖 автоотклик вкл' : ''}`
    : '';
// Напоминания (6.3): попытки робота за сутки по remind_at — отправлено, пропуски по итогам hh, сбои; очередь
const reminded = rows.filter((r) => at(r.remind_at) >= since);
const remindQueue = count(rows, (r) => r.remind_state);
const remindBy = (...keys) => count(reminded, (r) => keys.includes(r.remind_result));
const remindPart = (icon, n) => (n ? ` · ${icon} ${n}` : '');
const remindLineText =
  reminded.length || remindQueue
    ? `🔔 Напоминания: ${remindBy('sent')}${remindPart('👀', remindBy('viewed'))}${remindPart('🎉', remindBy('invited'))}${remindPart('❌', remindBy('rejected'))}${remindPart('💬', remindBy('wrote', 'already'))}${remindPart('🔒', remindBy('closed', 'archived', 'no_topic'))}${remindPart('🧪', remindBy('dry_run'))}${remindPart('⚠️', remindBy('error'))}${remindQueue ? ` · в очереди ${remindQueue}` : ''}`
    : '';
if (robotOn) {
  const h = $('Robot health').first()?.json ?? {};
  if (!h.ok || h.error) problems.push('робот-отклик не отвечает');
  else if (h.blocked) problems.push(`робот ждёт (${h.blocked.kind}) с ${localHM(at(h.blocked.since))}`);
  else if (!h.loggedIn) problems.push('робот не вошёл в hh');
}

const date = localDM(now);
const lines = [
  `☀️ <b>Сводка за сутки</b> · ${date}`,
  `🔎 Новых вакансий: ${fresh.length} → фильтр отсеял ${rejected.length}${topReasons ? ` (${topReasons})` : ''}`,
  resumeLine,
  `🤖 Оценено: ${scored.length}${scored.length ? ` — 🟢 ${count(scored, (r) => r.decision === 'apply')} · 🟡 ${count(scored, (r) => r.decision === 'maybe')} · 🔴 ${count(scored, (r) => r.decision === 'skip')}` : ''}${count(scored, (r) => r.decision === 'error') ? ` · ⚠️ ${count(scored, (r) => r.decision === 'error')}` : ''}`,
  `👤 Твои решения: ✅ ${count(mine, (r) => r.my_decision === 'apply')} · 🤔 ${count(mine, (r) => r.my_decision === 'maybe')} · ❌ ${count(mine, (r) => r.my_decision === 'skip')} · 📨 отправлено ${sent}${count(mine, (r) => r.my_decision === 'earlier') ? ` · 📨 раньше ${count(mine, (r) => r.my_decision === 'earlier')}` : ''}`,
  robotLineText,
  remindLineText,
  `⏳ Хвосты: без решения ${tailsWaiting} · ✅ без отклика ${tailsApproved}`,
  expired.size || archived.size ? `⌛ Устарели: ${expired.size} · 🔒 закрылись на hh: ${archived.size}` : '',
  shadow.pairs >= SHADOW_GOAL ? `${shadowLine(shadow)} — пора разбирать, напиши Claude` : shadowLine(shadow),
  sch.paused ? '⏸ Сбор на паузе (⚙️ Настройки → 🕐 Сбор)' : '',
  problems.length
    ? `⚠️ Сбои: ${problems.join(' · ')}`
    : `⚙️ Сборов ${collected}${sch.paused ? '' : ` из ${expected}`}, ошибок нет, туннель работает`,
];

return [{ json: { text: lines.filter(Boolean).join('\n'), silent: problems.length === 0 } }];

// W6 · Cleanup — убрать описания у отработанных вакансий старше 30 дней (07.10.2026).
// Нода: Code, режим «Run Once for All Items». Своя ветка ниже сводки: выполняется последней.
// Зачем: у таблиц лимит 100 МБ, а меню (W7) на каждое нажатие читает таблицу целиком. Строку не удаляем:
// по external_id и dup_key сбор узнаёт старые вакансии, а в меню видна история.
// Вход: «All rows». Выход: [{ id }] → «Save stripped» (description и snippet = ''), не больше 200 за раз.
// Отклики (applied), ✅ и 🤔 не трогаем: описание может понадобиться для письма и собеседования.

const DAY = 24 * 3600 * 1000;
const now = Date.now();
const DONE = ['rejected', 'skipped', 'expired', 'archived', 'seen'];

return $('All rows')
  .all()
  .map((i) => i.json)
  .filter(
    (r) =>
      r.id && DONE.includes(r.status) && (r.description || r.snippet) && now - (Date.parse(r.updatedAt) || now) > 30 * DAY,
  )
  .slice(0, 200)
  .map((r) => ({ json: { id: r.id } }));

// W6 · Unstick — строки, застрявшие в scoring дольше 30 мин, вернуть в detailed (07.10.2026).
// Нода: Code, режим «Run Once for All Items». Своя ветка ниже сводки.
// W2 «Claim» переводит строки detailed → scoring на время оценки, «Release» возвращает неотправленные.
// Если W2 упал посреди оценки, «Release» не выполнился — строку вернёт эта ветка, оценит следующий запуск W2.
// Вход: «All rows». Выход: [{ id }] → «Save unstuck».

const now = Date.now();
return $('All rows')
  .all()
  .map((i) => i.json)
  .filter((r) => r.id && r.status === 'scoring' && now - (Date.parse(r.updatedAt) || now) > 30 * 60 * 1000)
  .map((r) => ({ json: { id: r.id } }));
